import{_ as t,o,c as a,ah as r}from"./chunks/framework.DDXs_i7t.js";const g=JSON.parse('{"title":"March 23, 2026: The Wöginger Case – Gradual Withdrawal or Tactical Sacrifice?","description":"","frontmatter":{},"headers":[],"relativePath":"en/logbuch/2026-03-23-ruecktritt-woeginger.md","filePath":"en/logbuch/2026-03-23-ruecktritt-woeginger.md"}'),i={name:"en/logbuch/2026-03-23-ruecktritt-woeginger.md"};function n(s,e,c,l,h,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="march-23-2026-the-woginger-case-–-gradual-withdrawal-or-tactical-sacrifice" tabindex="-1">March 23, 2026: The Wöginger Case – Gradual Withdrawal or Tactical Sacrifice? <a class="header-anchor" href="#march-23-2026-the-woginger-case-–-gradual-withdrawal-or-tactical-sacrifice" aria-label="Permalink to &quot;March 23, 2026: The Wöginger Case – Gradual Withdrawal or Tactical Sacrifice?&quot;">​</a></h1><p>Today on Monday, the political landscape in Upper Austria is shaking: <strong>August Wöginger</strong>, parliamentary group leader of the ÖVP and a central figure in our &quot;Horten Mystery,&quot; is stepping down as deputy state party leader in Upper Austria. Officially because of &quot;work overload.&quot; Unofficially? A verdict in the trial for incitement to abuse of office (the patronage case) is imminent.</p><h2 id="the-facts-of-the-resignation" tabindex="-1">The Facts of the Resignation: <a class="header-anchor" href="#the-facts-of-the-resignation" aria-label="Permalink to &quot;The Facts of the Resignation:&quot;">​</a></h2><ul><li><strong>Date:</strong> Wöginger will no longer run as a candidate at the state party congress on April 24.</li><li><strong>Successor:</strong> Minister of Economic Affairs Wolfgang Hattmannsdorfer is ready to take over.</li><li><strong>Timing:</strong> The verdict at the Linz Regional Court is expected for April 21 – just three days before the party congress.</li></ul><h2 id="forum-analysis-the-voice-of-the-mob" tabindex="-1">Forum Analysis: The Voice of the &quot;Mob&quot; <a class="header-anchor" href="#forum-analysis-the-voice-of-the-mob" aria-label="Permalink to &quot;Forum Analysis: The Voice of the &quot;Mob&quot;&quot;">​</a></h2><p>A look at the user comments on <em>Der Standard</em> shows a clear picture. The cynicism is tangible, the mood towards the system of &quot;Hard Prose&quot; is at a low point:</p><ol><li><strong>The &quot;Work Overload&quot; Fable:</strong> Hardly any user believes the official reasoning. Comments like <em>&quot;Suddenly overloaded as the verdict approaches?&quot;</em> or <em>&quot;A classic resignation before being pushed out&quot;</em> dominate the forum.</li><li><strong>System Criticism:</strong> Many users draw the connection to forensic heroine <strong>Christa Scharf</strong>. The comments describe her as a figurehead against the &quot;deep state&quot; of ÖVP structures in Upper Austria.</li><li><strong>Fidelity (Nibelungentreue):</strong> There is heated debate about why Wöginger is allowed to keep his federal functions (parliamentary group leader) even if he is convicted. The tenor: <em>&quot;In this party, a guilty verdict apparently seems to be a qualification.&quot;</em></li></ol><h2 id="forensic-context" tabindex="-1">Forensic Context: <a class="header-anchor" href="#forensic-context" aria-label="Permalink to &quot;Forensic Context:&quot;">​</a></h2><p>For our project, this resignation is a crucial mosaic piece in the <strong>&quot;Pointillism of Money&quot;</strong>. It shows how the facade crumbles when the legal pressure becomes too great. We document this moment as part of <strong>Part 4: The political love story (and its bitter end)</strong>.</p><p>The traffic numbers for our Wöginger dossier have increased by <strong>340%</strong> since the news broke. The public is hungry for the &quot;Hard Prose.&quot;</p><hr><p><em>More on the reaction of the federal party tomorrow.</em></p>',12)])])}const f=t(i,[["render",n]]);export{g as __pageData,f as default};
